using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using NDShogi.Showcase.Core;

var results=new List<object>();int passed=0,failed=0;
void Assert(bool condition,string message="assertion failed"){if(!condition)throw new Exception(message);}
void Reject(Action action){bool rejected=false;try{action();}catch{rejected=true;}Assert(rejected,"fault was not detected");}
void Test(string name,Action body){try{body();passed++;results.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;results.Add(new{name,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+name+" "+e.Message);}}
GameState Position(PieceKind kind,Side side,Q4 at,params Piece[] others)=>new GameState(new[]{new Piece("mover",side,kind,at)}.Concat(others),side);
bool Legal(PieceKind kind,Side side,Q4 from,Q4 to,params Piece[] others)=>new RuleCore().IsLegal(Position(kind,side,from,others),new Move("mover",from,to));
var zero=new Q4(0,0,0,0);var core=new RuleCore();var initial=core.InitialState();
Test("initial-40-piece-standard-fixture",()=>{Assert(initial.Pieces.Count==40);Assert(initial.Pieces.All(p=>p.Position.V==0&&p.Position.W==0));Assert(initial.Pieces.Count(p=>p.Kind==PieceKind.Pawn)==18);Assert(initial.Pieces.Count(p=>p.Kind==PieceKind.King)==2);Assert(initial.At(new Q4(-3,-3,0,0))?.Kind==PieceKind.Rook);});
Test("fixed-dimension-and-unknown-occlusion-rejected",()=>{Reject(()=>new Ruleset(dimensions:2));Reject(()=>Ruleset.ParseOcclusion("plane/1"));Reject(()=>new Ruleset((OcclusionKind)99));});
Test("pawn-forward-and-transverse-symmetric",()=>{Assert(Legal(PieceKind.Pawn,Side.A,zero,new Q4(1,0,0,0)));Assert(!Legal(PieceKind.Pawn,Side.A,zero,new Q4(-1,0,0,0)));foreach(var q in new[]{new Q4(0,1,0,0),new Q4(0,-1,0,0),new Q4(0,0,1,0),new Q4(0,0,-1,0),new Q4(0,0,0,1),new Q4(0,0,0,-1)})Assert(Legal(PieceKind.Pawn,Side.A,zero,q));Assert(!Legal(PieceKind.Pawn,Side.A,zero,new Q4(1,1,0,0)));});
Test("B-3D-capability-fixed",()=>{Assert(!Legal(PieceKind.Pawn,Side.B,zero,new Q4(0,0,0,1)));Assert(Legal(PieceKind.Pawn,Side.B,zero,new Q4(0,0,1,0)));Assert(Legal(PieceKind.Pawn,Side.B,zero,new Q4(-1,0,0,0)));Reject(()=>new GameState(new[]{new Piece("B",Side.B,PieceKind.King,new Q4(0,0,0,1))}));});
Test("king-80-A-neighbors-26-B-neighbors",()=>{Assert(core.LegalMoves(Position(PieceKind.King,Side.A,zero)).Count==80);Assert(core.LegalMoves(Position(PieceKind.King,Side.B,zero)).Count==26);});
Test("gold-silver-knight-generalized-counts",()=>{Assert(core.LegalMoves(Position(PieceKind.Gold,Side.A,zero)).Count==14);Assert(core.LegalMoves(Position(PieceKind.Silver,Side.A,zero)).Count==13);Assert(core.LegalMoves(Position(PieceKind.Knight,Side.A,zero)).Count==6);});
Test("holder-rook-and-bishop-predicates",()=>{Assert(Legal(PieceKind.Rook,Side.A,zero,new Q4(0,0,0,4)));Assert(!Legal(PieceKind.Rook,Side.A,zero,new Q4(2,2,0,0)));Assert(Legal(PieceKind.Bishop,Side.A,zero,new Q4(0,3,0,-3)));Assert(!Legal(PieceKind.Bishop,Side.A,zero,new Q4(2,1,0,0)));Assert(!Legal(PieceKind.Bishop,Side.A,zero,new Q4(2,2,2,0)));});
Test("lance-sign-zero-boundaries-friendly-occupancy",()=>{Assert(Legal(PieceKind.Lance,Side.B,zero,new Q4(-4,0,0,0)));Assert(!Legal(PieceKind.Lance,Side.B,zero,new Q4(4,0,0,0)));Assert(!Legal(PieceKind.King,Side.A,zero,zero));Assert(!Legal(PieceKind.King,Side.A,new Q4(4,0,0,0),new Q4(5,0,0,0)));Assert(!Legal(PieceKind.Pawn,Side.A,zero,new Q4(1,0,0,0),new Piece("friend",Side.A,PieceKind.Pawn,new Q4(1,0,0,0))));});
Test("slider-blocking-and-knight-jump-exception",()=>{var blocker=new Piece("block",Side.A,PieceKind.Pawn,new Q4(1,0,0,0));Assert(!Legal(PieceKind.Rook,Side.A,zero,new Q4(3,0,0,0),blocker));Assert(Legal(PieceKind.Knight,Side.A,zero,new Q4(2,1,0,0),blocker));});
Test("exact-supercover-known-corner-difference",()=>{var from=new[]{0,0,0,0};var to=new[]{2,2,0,0};var cell=new[]{1,0,0,0};Assert(!Occlusion.CellBlocks(from,to,cell,OcclusionKind.LatticeLine));Assert(Occlusion.CellBlocks(from,to,cell,OcclusionKind.SupercoverClosed));Assert(!Occlusion.CellBlocks(from,to,from,OcclusionKind.SupercoverClosed));Assert(!Occlusion.CellBlocks(from,to,to,OcclusionKind.SupercoverClosed));});
Test("occlusion-choice-affects-authoritative-legality",()=>{var pieces=new[]{new Piece("m",Side.A,PieceKind.Bishop,zero),new Piece("obstacle",Side.B,PieceKind.Pawn,new Q4(1,0,0,0))};var move=new Move("m",zero,new Q4(2,2,0,0));foreach(var o in new[]{OcclusionKind.LatticeLine,OcclusionKind.SupercoverClosed}){var rules=new Ruleset(o);Assert(new RuleCore(rules).IsLegal(new GameState(pieces,rules:rules),move)==(o==OcclusionKind.LatticeLine));}});
Test("hidden-pieces-retain-occupancy-and-attacks",()=>{var from=new Q4(0,0,0,1);var blocker=new Piece("hidden-blocker",Side.A,PieceKind.Pawn,new Q4(1,0,0,1));Assert(!Legal(PieceKind.Rook,Side.A,from,new Q4(3,0,0,1),blocker));var state=new GameState(new[]{new Piece("hidden-attacker",Side.A,PieceKind.Rook,new Q4(4,0,0,1)),new Piece("king",Side.B,PieceKind.King,new Q4(4,0,0,0)),new Piece("pawn",Side.B,PieceKind.Pawn,new Q4(2,-4,0,0))},Side.B);Assert(core.Attackers(state,new Q4(4,0,0,0),Side.A).Count==1);Assert(core.IsLegal(state,new Move("pawn",new Q4(2,-4,0,0),new Q4(1,-4,0,0))),"hidden attacks must not impose self-check restriction");});
Test("capture-king-terminal-no-promotion-drops",()=>{var state=new GameState(new[]{new Piece("a",Side.A,PieceKind.Pawn,new Q4(4,0,0,1)),new Piece("k",Side.B,PieceKind.King,new Q4(4,0,0,0))});var after=core.Apply(state,new Move("a",new Q4(4,0,0,1),new Q4(4,0,0,0)));Assert(after.Outcome==GameOutcome.KingCapture&&after.Winner==Side.A&&after.Captured.Count==1&&after.Pieces.Single().Kind==PieceKind.Pawn);Assert(core.LegalMoves(after).Count==0);});
Test("no-legal-moves-draw",()=>{var state=new GameState(new[]{new Piece("a",Side.A,PieceKind.Pawn,zero)});var after=core.Apply(state,new Move("a",zero,new Q4(1,0,0,0)));Assert(after.Outcome==GameOutcome.NoLegalMovesDraw&&after.Winner==null);});
Test("source-state-immutable-and-sparse",()=>{var list=initial.Pieces.ToList();var state=new GameState(list);var hash=state.Hash;list.Clear();Assert(state.Pieces.Count==40&&state.Hash==hash);Assert(typeof(GameState).GetFields(System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).All(f=>f.FieldType!=typeof(Piece[,,,])));});
Test("transaction-cancel-pause-reserve-and-single-commit",()=>{var tx=new MoveTransaction(core,initial);var move=new Move("A-Pawn-0",new Q4(-2,0,0,0),new Q4(-1,0,0,0));tx.Reserve(move);Assert(tx.State.Hash==initial.Hash);Reject(()=>tx.Reserve(move));tx.Cancel();Assert(tx.State.Hash==initial.Hash);Reject(()=>tx.Commit());tx.Reserve(move);var after=tx.Commit();Assert(after.Ply==1&&tx.CommitCount==1);Reject(()=>tx.Commit());tx.Restart(initial);Assert(tx.State.Hash==initial.Hash&&tx.CommitCount==0&&!tx.HasReservation);});

ScenarioResult? run=null;var runner=new ScenarioRunner();
Test("directed-live-complete-27-ply-cpu-evaluated-route",()=>{run=runner.RunToEnd();Assert(run.Records.Count==ScenarioRunner.ExpectedPlies&&run.FinalState.Winner==Side.A&&run.FinalState.Pieces.Count==ScenarioRunner.ExpectedRemainingPieceCount);Assert(run.Records.All(r=>r.Decision.Candidates.Count>0&&r.Decision.NodesVisited<=5000));Assert(run.Records.Where(r=>r.BeforeState.Turn==Side.B).All(r=>r.Decision.Candidates.Sum(c=>c.ReplyNodes)>0));Assert(run.Records.Where(r=>r.BeforeState.Turn==Side.A).All(r=>r.Move.PieceId==PawnFirst4D.HeroId&&!r.Decision.NonPawnRescue));});
Test("scene-pressure-three-height-exchanges-hidden-ending-guards",()=>{Assert(run!=null);var r=run!;Assert(r.Records[3].Guards.Contains("hero-under-authoritative-attack"));for(int exchange=0;exchange<ScenarioRunner.ThreeDExchangeCount;exchange++){int a=ScenarioRunner.First3DPly-1+2*exchange,b=a+1;Assert(r.Records[a].AfterState.Find(PawnFirst4D.HeroId)?.Position==new Q4(0,0,exchange+1,0));Assert(r.Records[b].Guards.Contains("B-observed-height-response")&&r.Records[b].Guards.Contains("hero-under-authoritative-attack"));}var hidden=r.Records[ScenarioRunner.First4DPly-1].AfterState;Assert(hidden.Find(PawnFirst4D.HeroId)?.Position.W==1);Assert(!ObservationFactory.ForB(hidden).Pieces.Any(p=>p.Id==PawnFirst4D.HeroId));Assert(r.Records[ScenarioRunner.ExpectedPlies-1].CapturedId=="B-King-0");});
Test("ordinary-B-mixed-piece-development-after-escape",()=>{var replies=run!.Records.Where(r=>r.Ply>ScenarioRunner.First4DPly&&r.BeforeState.Turn==Side.B).ToArray();var kinds=replies.Select(r=>r.BeforeState.Find(r.Move.PieceId)!.Kind).Distinct().ToArray();Assert(new[]{PieceKind.Silver,PieceKind.Gold,PieceKind.Rook,PieceKind.Pawn}.All(k=>kinds.Contains(k)));Assert(replies.All(r=>r.Move.From.V==0&&r.Move.To.V==0&&r.Move.From.W==0&&r.Move.To.W==0));Assert(run.Records[1].BeforeState.Find(run.Records[1].Move.PieceId)!.Kind==PieceKind.Silver);});
Test("ordinary-B-development-does-not-use-escape-ply",()=>{var obs=ObservationFactory.ForB(run!.Records[ScenarioRunner.First4DPly-1].AfterState);var changed=new Observation3D(obs.Pieces,obs.Turn,101);var b=new Tactical3D(OcclusionKind.LatticeLine);var one=b.Decide(obs,123);var two=b.Decide(changed,123);Assert(one.Move.Equals(two.Move)&&one.NodesVisited==two.NodesVisited);Assert(one.Candidates.Select(c=>c.Move.Key+":"+c.Total+":"+c.ReplyNodes).SequenceEqual(two.Candidates.Select(c=>c.Move.Key+":"+c.Total+":"+c.ReplyNodes)));});
Test("four-dimensional-presentation-metadata-alternates-one-move",()=>{int shown=0;foreach(var record in run!.Records){bool rotated=ScenarioRunner.Requires4DViewForPly(record.Ply);if(rotated){shown++;Assert(record.BeforeState.Turn==Side.A&&(record.Move.From.W==1||record.Move.To.W==1));if(record.Ply<ScenarioRunner.ExpectedPlies)Assert(run.Records[record.Ply].BeforeState.Turn==Side.B&&!ScenarioRunner.Requires4DViewForPly(record.Ply+1));}if(record.BeforeState.Turn==Side.B)Assert(!rotated);}Assert(shown==9&&ScenarioRunner.Requires4DViewForPly(ScenarioRunner.ExpectedPlies));});
Test("early-four-dimensional-escape-is-rejected-by-scenario-guard",()=>{var before=run!.Records[5].AfterState;var hero=before.Find(PawnFirst4D.HeroId)!;var move=new Move(hero.Id,hero.Position,hero.Position+new Q4(0,0,0,1));Assert(core.IsLegal(before,move));var decision=new CpuDecision("fault",move,before.Hash,Array.Empty<CandidateScore>(),0,0,0,"Deliberately skip remaining 3D exchanges.");Reject(()=>runner.RecordCommitted(before,core.Apply(before,move),decision));});
Test("repeat-seed-identical-candidates-and-transcript",()=>{Assert(run!=null);var again=runner.RunToEnd();Assert(run!.TranscriptHash==again.TranscriptHash);Assert(run.Records.Select(r=>r.Decision.Fingerprint).SequenceEqual(again.Records.Select(r=>r.Decision.Fingerprint)));});
Test("verified-replay-revalidates-and-identifies-mode",()=>{var replay=runner.Replay(run!);Assert(replay.Mode==ExecutionMode.VerifiedReplay&&replay.TranscriptHash==run!.TranscriptHash);Assert(replay.Records.All(r=>r.Decision.Cpu=="VerifiedReplay/1"&&r.Decision.NodesVisited==0));});
Test("portable-replay-fixture-loads-without-live-CPU",()=>{var text=ScenarioRunner.ExportReplay(run!);var replay=runner.LoadReplay(text);Assert(replay.TranscriptHash==run!.TranscriptHash);var tx=new MoveTransaction(runner.Core,replay.InitialState);foreach(var r in replay.Records){var decision=runner.DecideReplayNext(tx.State,replay);Assert(decision.NodesVisited==0&&decision.Candidates.Count==0);tx.Reserve(decision.Move);tx.Commit();Assert(tx.State.Hash==r.AfterHash);}Assert(tx.State.Hash==run.FinalState.Hash);});
Test("portable-replay-tamper-and-wrong-occlusion-rejected",()=>{var text=ScenarioRunner.ExportReplay(run!);Reject(()=>runner.LoadReplay(text.Replace("-1,0,0,0","4,4,4,4")));Reject(()=>Bootstrap.CreateScenario(OcclusionKind.SupercoverClosed).LoadReplay(text));Reject(()=>runner.LoadReplay(text.Replace(run!.TranscriptHash,new string('0',64))));});
Test("B-counterfactual-hidden-location-kind-count-invariance",()=>{var state=run!.Records[ScenarioRunner.First4DPly-1].AfterState;var baseline=ObservationFactory.ForB(state);var changed=new GameState(state.Pieces.Where(p=>p.Id!=PawnFirst4D.HeroId).Concat(new[]{new Piece(PawnFirst4D.HeroId,Side.A,PieceKind.Rook,new Q4(-3,2,3,-2))}),state.Turn,state.Ply,state.Rules,state.Captured);var b=new Tactical3D(state.Rules.Occlusion);var one=b.Decide(baseline,123);var two=b.Decide(ObservationFactory.ForB(changed),123);Assert(state.Hash!=changed.Hash);ObservationBoundaryAudit.RequireNoninterference(one,two);var extra=new GameState(changed.Pieces.Concat(new[]{new Piece("unknown-hidden",Side.A,PieceKind.King,new Q4(3,-2,-2,2))}),changed.Turn,changed.Ply,changed.Rules,changed.Captured);ObservationBoundaryAudit.RequireNoninterference(one,b.Decide(ObservationFactory.ForB(extra),123));});
Test("B-boundary-full-state-and-hash-injection-rejected",()=>{var obs=ObservationFactory.ForB(run!.Records[ScenarioRunner.First4DPly-1].AfterState);ObservationBoundaryAudit.RequireAllowedInput(obs);Reject(()=>ObservationBoundaryAudit.RequireAllowedInput(new{Observation=obs,FullState=run.FinalState}));Reject(()=>ObservationBoundaryAudit.RequireAllowedInput(new{Observation=obs,FullHash=run.FinalState.Hash}));Reject(()=>ObservationBoundaryAudit.RequireAllowedInput(new{Observation=obs,FullAttackTable=core.Attackers(run.FinalState,new Q4(4,0,0,0),Side.A)}));Reject(()=>ObservationBoundaryAudit.RequireAllowedInput(new{Observation=obs,HiddenEndpoint=new Q4(4,0,0,1)}));});
Test("B-leaky-policy-mutation-detected",()=>{var state=run!.Records[ScenarioRunner.First4DPly-1].AfterState;var b=new Tactical3D(state.Rules.Occlusion);var decision=b.Decide(ObservationFactory.ForB(state),123);var injected=new CpuDecision(decision.Cpu,decision.Move,decision.ObservationHash,decision.Candidates.Select((c,i)=>new CandidateScore(c.Move,c.TacticalScore+(i==0?1:0),c.PreferenceScore,c.ReplyNodes)),decision.Seed,decision.NodeBudget,decision.NodesVisited,"injected hidden-state score");Reject(()=>ObservationBoundaryAudit.RequireNoninterference(decision,injected));});
Test("display-independent-observation-and-selection",()=>{var state=run!.Records[ScenarioRunner.First4DPly-1].AfterState;var stateA=run.Records[ScenarioRunner.First4DPly-1].BeforeState;var a=new PawnFirst4D();var aExpected=a.Decide(stateA,core,77);var legalKeys=string.Join(";",core.LegalMoves(stateA).Select(m=>m.Key));var b=new Tactical3D(state.Rules.Occlusion);var expected=b.Decide(ObservationFactory.ForB(state),77);for(int angle=0;angle<=90;angle+=15){var fakeRendererVisible=state.Pieces.Where(p=>(p.Position.U+angle)%3==0).ToArray();Assert(fakeRendererVisible!=null);ObservationBoundaryAudit.RequireNoninterference(expected,b.Decide(ObservationFactory.ForB(state),77));Assert(aExpected.Fingerprint==a.Decide(stateA,core,77).Fingerprint);Assert(legalKeys==string.Join(";",core.LegalMoves(stateA).Select(m=>m.Key)));}Assert(state.Hash==run.Records[ScenarioRunner.First4DPly-1].AfterHash&&stateA.Hash==run.Records[ScenarioRunner.First4DPly-1].BeforeHash);});
Test("independent-verifier-rejects-illegal-move-mutation",()=>{var records=run!.Records.ToArray();var r=records[2];var wrong=new Move(r.Move.PieceId,r.Move.From,new Q4(4,4,4,4));var bad=new CpuDecision("mutant",wrong,r.Decision.ObservationHash,Array.Empty<CandidateScore>(),0,0,0,"fault injection");records[2]=new PlyRecord(r.BeforeState,r.AfterState,bad,r.Scene,r.Guards);var corrupt=new ScenarioResult(run.InitialState,run.FinalState,records,run.Mode,run.Seed);Reject(()=>IndependentRuleVerifier.Verify(corrupt));Reject(()=>runner.Replay(corrupt));});
Test("independent-verifier-rejects-state-warp",()=>{var records=run!.Records.ToArray();var r=records[5];var altered=new GameState(r.AfterState.Pieces.Select(p=>p.Id==PawnFirst4D.HeroId?p.At(new Q4(2,0,1,0)):p),r.AfterState.Turn,r.AfterState.Ply,r.AfterState.Rules,r.AfterState.Captured);records[5]=new PlyRecord(r.BeforeState,altered,r.Decision,r.Scene,r.Guards);Reject(()=>IndependentRuleVerifier.Verify(new ScenarioResult(run.InitialState,run.FinalState,records,run.Mode,run.Seed)));});
Test("independent-rule-crosscheck-eight-kinds-both-occlusions",()=>{int checkedMoves=0;foreach(var mode in new[]{OcclusionKind.LatticeLine,OcclusionKind.SupercoverClosed})foreach(PieceKind kind in Enum.GetValues(typeof(PieceKind)))foreach(Side side in Enum.GetValues(typeof(Side))){var c=new RuleCore(new Ruleset(mode));var state=new GameState(new[]{new Piece("m",side,kind,zero),new Piece("block",RuleCore.Other(side),PieceKind.Pawn,new Q4(1,0,0,0))},side,rules:c.Rules);foreach(var move in c.LegalMoves(state)){IndependentRuleVerifier.CheckMove(state.Pieces,state.Find("m")!,move.To,mode);checkedMoves++;}}Assert(checkedMoves>500);});
Test("independent-verifier-rejects-blocked-slider",()=>{var p=new Piece("m",Side.A,PieceKind.Bishop,zero);var block=new Piece("b",Side.B,PieceKind.Pawn,new Q4(1,0,0,0));IndependentRuleVerifier.CheckMove(new[]{p,block},p,new Q4(2,2,0,0),OcclusionKind.LatticeLine);Reject(()=>IndependentRuleVerifier.CheckMove(new[]{p,block},p,new Q4(2,2,0,0),OcclusionKind.SupercoverClosed));});
Test("alternate-occlusion-is-explicit-separate-run",()=>{var alternative=Bootstrap.CreateScenario(OcclusionKind.SupercoverClosed).RunToEnd();Assert(alternative.InitialState.Rules.OcclusionId=="supercover-closed/1");Assert(alternative.InitialState.Hash!=run!.InitialState.Hash);});
Test("all-run-snapshots-preserve-rules-and-capabilities",()=>{Assert(run!.Records.All(r=>r.BeforeState.Rules.Occlusion==OcclusionKind.LatticeLine&&r.AfterState.Rules.Occlusion==OcclusionKind.LatticeLine&&r.AfterState.Pieces.Where(p=>p.Side==Side.B).All(p=>p.Position.W==0)));});

string evidence=args.Length>0?Path.GetFullPath(args[0]):Path.GetFullPath("evidence/core");Directory.CreateDirectory(evidence);File.WriteAllText(Path.Combine(evidence,"tests.json"),JsonSerializer.Serialize(new{status=failed==0?"PASS":"FAIL",passed,failed,tests=results},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"Tests: {passed} passed, {failed} failed.");Environment.ExitCode=failed==0?0:1;
